m = int(input())
def better(a, b):
    if len(a) != len(b):
        return a if len(a) > len(b) else b
    return a if a > b else b
dp = [""] * (m + 1)
if n > 0 and price[0] <= m:
    dp[price[0]] = "0"
for cost in range(m + 1):
    if not dp[cost]:
        continue
    for d in range(n):
        if dp[cost] == "0":
            continue
        nc = cost + price[d]
        if nc <= m:
            dp[nc] = better(dp[nc], dp[cost] + str(d))
for d in range(1, n):
    if price[d] <= m:
        dp[price[d]] = better(dp[price[d]], str(d))
        for cost in range(price[d], m + 1):
            if not dp[cost]:
                continue
            for nd in range(n):
                nc = cost + price[nd]
                if nc <= m:
                    dp[nc] = better(dp[nc], dp[cost] + str(nd))
ans = "0"
for value in dp:
    if value:
        ans = better(ans, value)
print(ans)

