input = sys.stdin.readline
n = int(input())
parent = list(range(n))
def val(ch):
    if ch == "0":
        return 0
    if "a" <= ch <= "z":
        return ord(ch) - 96
    return ord(ch) - 38
def find(x):
    while parent[x] != x:
        parent[x] = parent[parent[x]]
        x = parent[x]
    return x
def union(a, b):
    ra, rb = find(a), find(b)
    if ra == rb:
        return False
    parent[rb] = ra
    return True
edges = []
total = 0
for i in range(n):
    row = input().strip()
    for j, ch in enumerate(row):
        w = val(ch)
        total += w
        if i != j and w:
            edges.append((w, i, j))
used = cnt = 0
for w, a, b in sorted(edges):
    if union(a, b):
        used += w
        cnt += 1
print(total - used if cnt == n - 1 else -1)

