import sys
n = int(sys.stdin.readline())
if n < 2:
    print(0)
else:
    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            for j in range(i * i, n + 1, i):
                sieve[j] = False
    primes = [i for i in range(n + 1) if sieve[i]]
    left = total = ans = 0
    for right in range(len(primes)):
        total += primes[right]
        while total > n and left <= right:
            total -= primes[left]
            left += 1
        if total == n:
            ans += 1
    print(ans)

