def solve(r, c, size):
    first = a[r][c]
    ok = True
    for i in range(r, r + size):
        for j in range(c, c + size):
            if a[i][j] != first:
                ok = False
                break
        if not ok:
            break
    if ok:
        ans[first] += 1
        return
    step = size // 3
    for dr in range(3):
        for dc in range(3):
            solve(r + dr * step, c + dc * step, step)
