def check(line):
    steps = line.split()
    broken = [False] * 5
    dip_bad = [False] * len(steps)
    for i, step in enumerate(steps):
        if step == 'dip':
            ok = (i >= 1 and steps[i - 1] == 'jiggle') or (i >= 2 and steps[i - 2] == 'jiggle') or (i + 1 < len(steps) and steps[i + 1] == 'twirl')
