    if steps and steps[0] == 'jiggle':
        broken[3] = True
    if 'dip' not in steps:
        broken[4] = True
    fixed = [step.upper() if step == 'dip' and dip_bad[i] else step for i, step in enumerate(steps)]
    errors = [str(i + 1) for i, value in enumerate(broken) if value]
