import sys

pairs = {")": "(", "]": "["}

def balanced(line):
    stack = []
    for ch in line:
        if ch in "([":
            stack.append(ch)
        elif ch in ")]":
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack

