import functools, sys
input = sys.stdin.readline
order = {ch: i for i, ch in enumerate('AaBbCcDdEeFfGgHhIiJjKkLlMmNnOoPpQqRrSsTtUuVvWwXxYyZz')}

def tokens(s):
    result = []
    i = 0
    while i < len(s):
        if s[i].isdigit():
            j = i
            while j < len(s) and s[j].isdigit():
                j += 1
            result.append(('num', s[i:j]))
            i = j
        else:
            result.append(('chr', s[i]))
            i += 1
    return result

def cmp(a, b):
    ta, tb = tokens(a), tokens(b)
    for x, y in zip(ta, tb):
        if x[0] != y[0]:
            return -1 if x[0] == 'num' else 1
        if x[0] == 'chr':
            if x[1] != y[1]:
                return order[x[1]] - order[y[1]]
        else:
            ax = x[1].lstrip('0') or '0'
            by = y[1].lstrip('0') or '0'
            if len(ax) != len(by):
                return len(ax) - len(by)
            if ax != by:
                return -1 if ax < by else 1
            az = len(x[1]) - len(x[1].lstrip('0'))
            bz = len(y[1]) - len(y[1].lstrip('0'))
            if az != bz:
                return az - bz
    return len(ta) - len(tb)

n = int(input())
arr = [input().strip() for _ in range(n)]
print('\n'.join(sorted(arr, key=functools.cmp_to_key(cmp))))

import sys
input = sys.stdin.readline
n, r = map(int, input().split())
size = 1 << n
arr = [list(map(int, input().split())) for _ in range(size)]

def rotate_clock(block):
    return [list(row) for row in zip(*block[::-1])]

def rotate_counter(block):
    return [list(row) for row in zip(*block)][::-1]

def apply_inside(a, level, op):
    b = 1 << level
    out = [row[:] for row in a]
    for sr in range(0, size, b):
        for sc in range(0, size, b):
            block = [row[sc:sc + b] for row in a[sr:sr + b]]
            if op == 1:
                block = block[::-1]
            elif op == 2:
                block = [row[::-1] for row in block]
            elif op == 3:
                block = rotate_clock(block)
            elif op == 4:
                block = rotate_counter(block)
            for i in range(b):
                out[sr + i][sc:sc + b] = block[i]
    return out

def apply_whole(a, level, op):
    b = 1 << level
    count = size // b
    blocks = [[None] * count for _ in range(count)]
    for i in range(count):
        for j in range(count):
            blocks[i][j] = [row[j * b:(j + 1) * b] for row in a[i * b:(i + 1) * b]]
    if op == 5:
        blocks = blocks[::-1]
    elif op == 6:
        blocks = [row[::-1] for row in blocks]
    elif op == 7:
        blocks = [list(row) for row in zip(*blocks[::-1])]
    elif op == 8:
        blocks = [list(row) for row in zip(*blocks)][::-1]
    out = [[0] * size for _ in range(size)]
    for i in range(count):
        for j in range(count):
            for x in range(b):
                out[i * b + x][j * b:(j + 1) * b] = blocks[i][j][x]
    return out

for _ in range(r):
    op, level = map(int, input().split())
    if op <= 4:
        arr = apply_inside(arr, level, op)
    else:
        arr = apply_whole(arr, level, op)
print('\n'.join(' '.join(map(str, row)) for row in arr))

