a = list(map(int, input().split()))
def can(limit):
    ok = [False] * n
    ok[0] = True
    for i in range(n):
        if not ok[i]:
            continue
        for j in range(i + 1, n):
            power = (j - i) * (1 + abs(a[i] - a[j]))
            if power <= limit:
                ok[j] = True
    return ok[-1]
lo, hi = 0, (n - 1) * (1 + max(a) - min(a))
while lo < hi:
    mid = (lo + hi) // 2
    if can(mid):
        hi = mid
    else:
        lo = mid + 1
